package imagestore

import (
	"container/list"
	"os"
	"strconv"
	"sync"
)

// ThumbnailCache is a very small in-process LRU that caches thumbnails generated by (assetID, thumbKB).
//
// It exists because reading from disk is cheap for the local backend, but every read of the source image from the S3 backend goes out over the network,
// and thumbnail regeneration also costs CPU. On an LRU hit, c.Data() is returned directly, with zero origin reads.
//
// Design trade-offs:
//   - not persisted (reset on restart; the data is small enough)
//   - the mime is not encoded in the key; when different backends or formats regenerate, old entries are naturally evicted by capBytes
//   - a 64MB default limit, evicted by bytes; a single image that is too large (>capBytes) is not cached
type ThumbnailCache struct {
	mu       sync.Mutex
	ll       *list.List
	idx      map[string]*list.Element
	capBytes int64
	curBytes int64
}

type thumbEntry struct {
	key         string
	contentType string
	data        []byte
}

// NewThumbnailCache creates an LRU with a capacity of capBytes bytes. When capBytes <= 0 it uses the 64MB default.
func NewThumbnailCache(capBytes int64) *ThumbnailCache {
	if capBytes <= 0 {
		capBytes = 64 * 1024 * 1024
		if value, err := strconv.ParseInt(os.Getenv("IMAGE_THUMB_CACHE_MB"), 10, 64); err == nil && value >= 1 && value <= 1024 {
			capBytes = value * 1024 * 1024
		}
	}
	return &ThumbnailCache{
		ll:       list.New(),
		idx:      make(map[string]*list.Element),
		capBytes: capBytes,
	}
}

// ThumbKey builds the cache key.
func ThumbKey(assetID int64, thumbKB int) string {
	return strconv.FormatInt(assetID, 10) + ":" + strconv.Itoa(thumbKB)
}

// Get returns (data, contentType, true) on a hit.
func (c *ThumbnailCache) Get(key string) ([]byte, string, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	el, ok := c.idx[key]
	if !ok {
		return nil, "", false
	}
	c.ll.MoveToFront(el)
	en := el.Value.(*thumbEntry)
	return en.data, en.contentType, true
}

// Put writes the entry. data larger than capBytes is silently ignored.
func (c *ThumbnailCache) Put(key, contentType string, data []byte) {
	if len(data) == 0 || int64(len(data)) > c.capBytes {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()

	if el, ok := c.idx[key]; ok {
		en := el.Value.(*thumbEntry)
		c.curBytes -= int64(len(en.data))
		en.contentType = contentType
		en.data = data
		c.curBytes += int64(len(data))
		c.ll.MoveToFront(el)
	} else {
		en := &thumbEntry{key: key, contentType: contentType, data: data}
		el := c.ll.PushFront(en)
		c.idx[key] = el
		c.curBytes += int64(len(data))
	}

	for c.curBytes > c.capBytes {
		oldest := c.ll.Back()
		if oldest == nil {
			break
		}
		en := oldest.Value.(*thumbEntry)
		c.ll.Remove(oldest)
		delete(c.idx, en.key)
		c.curBytes -= int64(len(en.data))
	}
}

// Invalidate clears all thumbKB variants when the asset is deleted.
func (c *ThumbnailCache) Invalidate(assetID int64) {
	prefix := strconv.FormatInt(assetID, 10) + ":"
	c.mu.Lock()
	defer c.mu.Unlock()
	for key, el := range c.idx {
		if !startsWith(key, prefix) {
			continue
		}
		en := el.Value.(*thumbEntry)
		c.ll.Remove(el)
		delete(c.idx, key)
		c.curBytes -= int64(len(en.data))
	}
}

func startsWith(s, prefix string) bool {
	return len(s) >= len(prefix) && s[:len(prefix)] == prefix
}
